import { test, expect } from '@playwright/test';

test.describe('Login Form Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should navigate login form fields using arrow keys', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Focus on email input using Tab
    const emailInput = page.getByLabel(/email/i);
    await emailInput.focus();
    await expect(emailInput).toBeFocused();

    // Verify email input has focus
    await expect(emailInput).toHaveAttribute('data-testid', /email-input/);

    // Navigate to password input using Tab
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.focus();
    await expect(passwordInput).toBeFocused();

    // Verify password input has focus
    await expect(passwordInput).toHaveAttribute('data-testid', /password-input/);

    // Navigate to submit button using Tab
    const submitButton = page.getByRole('button', { name: /sign in/i });
    await submitButton.focus();
    await expect(submitButton).toBeFocused();

    // Verify submit button has focus
    await expect(submitButton).toHaveAttribute('data-testid', /submit-button/);

    // Verify submit button is visible and enabled
    await expect(submitButton).toBeVisible();
    await expect(submitButton).toBeEnabled();
  });

  test('should handle arrow key navigation within login form', async ({ page }) => {
    // Focus on email input using Tab
    const emailInput = page.getByLabel(/email/i);
    await emailInput.focus();

    // Navigate to password input using Down arrow
    await emailInput.press('ArrowDown');
    await expect(passwordInput).toBeFocused();

    // Navigate to submit button using Down arrow
    await passwordInput.press('ArrowDown');
    await expect(submitButton).toBeFocused();

    // Navigate back to email input using Up arrow
    await submitButton.press('ArrowUp');
    await expect(emailInput).toBeFocused();

    // Navigate to password input using Down arrow
    await emailInput.press('ArrowDown');
    await expect(passwordInput).toBeFocused();

    // Verify form is still accessible and valid
    await expect(loginForm).toBeVisible();
    await expect(submitButton).toBeEnabled();
  });
});
